<?php

declare(strict_types=1);

function palPageSalesList(): void { $u=palCurrentUser(); $t=__DIR__.'/../templates/project-audit-ledger/shell.disyl'; palRender($t, ['current_user'=>$u, 'page_title'=>'Sales', 'page_content'=>'sales-list']); }
function palPageSalesDetail(array $rp=[]): void { $u=palCurrentUser(); $id=(int)($rp['id']??$_GET['id']??0); $s=new palSalesService(palDb(), (int)($u['tenant_id']??0), (int)$u['id']); $sale=$s->get($id); if(!$sale){palJsonError('Sale not found.',404);return;} $displayNum=$sale['invoice_number']?:$sale['sales_number']; $t=__DIR__.'/../templates/project-audit-ledger/shell.disyl'; palRender($t, ['current_user'=>$u, 'page_title'=>'Invoice #'.$displayNum, 'page_content'=>'sales-detail', 'sale'=>$sale]); }
function palPageSalesForm(array $rp = []): void { $u=palCurrentUser(); $id=(int)($rp['id']??$_GET['id']??0); $sale=null; if($id>0){$s=new palSalesService(palDb(), (int)($u['tenant_id']??0), (int)$u['id']); $sale=$s->get($id); if($sale && empty($sale['invoice_number'])){$sale['invoice_number']=$sale['sales_number'];} } $db=palDb(); $tid=(int)($u['tenant_id']??0); $proj=$db->prepare("SELECT id,title FROM pal_projects WHERE tenant_id=:tid AND status IN('approved','started','ongoing','completed') ORDER BY title"); $proj->execute([':tid'=>$tid]); $clients=$db->prepare("SELECT id,name FROM pal_clients WHERE tenant_id=:tid AND is_active=1 ORDER BY name"); $clients->execute([':tid'=>$tid]); $materials=$db->prepare("SELECT m.id, m.name, m.material_code, m.price_per_unit, m.price_per_sqft, m.default_width, m.default_height, mc.name AS category_name FROM pal_materials m LEFT JOIN pal_material_categories mc ON m.category_id=mc.id WHERE m.tenant_id=:tid AND m.is_active=1 ORDER BY m.name"); $materials->execute([':tid'=>$tid]); $t=__DIR__.'/../templates/project-audit-ledger/shell.disyl'; palRender($t, ['current_user'=>$u, 'page_title'=>$sale?'Edit Sale':'Create Sale', 'page_content'=>'sales-form', 'sale'=>$sale, 'is_edit'=>$sale!==null, 'projects'=>$proj->fetchAll(PDO::FETCH_ASSOC), 'clients'=>$clients->fetchAll(PDO::FETCH_ASSOC), 'materials'=>$materials->fetchAll(PDO::FETCH_ASSOC)]); }
function palPageCollectionList(): void { $u=palCurrentUser(); $db=palDb(); $tid=(int)($u['tenant_id']??0); $tab=$_GET['tab']??'all'; $statusFilter=$tab!=='all'?($tab==='paid'?'approved':$tab):''; $search=$_GET['search']??''; // Stats
$stats=$db->query("SELECT COUNT(*) AS total, COALESCE(SUM(CASE WHEN status='pending' THEN 1 ELSE 0 END),0) AS pending_count, COALESCE(SUM(CASE WHEN status='pending' THEN amount ELSE 0 END),0) AS pending_amount, COALESCE(SUM(CASE WHEN status='approved' THEN 1 ELSE 0 END),0) AS approved_count, COALESCE(SUM(CASE WHEN status='approved' THEN amount ELSE 0 END),0) AS approved_amount, COALESCE(SUM(CASE WHEN status='rejected' THEN 1 ELSE 0 END),0) AS rejected_count, COALESCE(SUM(CASE WHEN status='voided' THEN 1 ELSE 0 END),0) AS voided_count FROM pal_collections WHERE tenant_id=$tid")->fetch(PDO::FETCH_ASSOC); // List with filtering
$where='c.tenant_id=:tid'; $params=[':tid'=>$tid]; if($statusFilter){$where.=' AND c.status=:st'; $params[':st']=$statusFilter;} if($search){$where.=' AND (c.collection_number LIKE :sq OR cl.name LIKE :sq2)'; $params[':sq']="%$search%"; $params[':sq2']="%$search%";} $rows=$db->prepare("SELECT c.id, c.collection_number, c.amount, c.payment_method, c.status, c.payment_date, c.created_at, COALESCE(s.invoice_number, s.sales_number) AS sales_number, p.title AS project_title, cl.name AS client_name FROM pal_collections c LEFT JOIN pal_sales s ON c.sales_id=s.id LEFT JOIN pal_projects p ON c.project_id=p.id LEFT JOIN pal_clients cl ON c.client_id=cl.id WHERE $where ORDER BY c.created_at DESC LIMIT 100"); $rows->execute($params); $t=__DIR__.'/../templates/project-audit-ledger/shell.disyl'; palRender($t, ['current_user'=>$u, 'page_title'=>'Collections', 'page_content'=>'collections-list', 'stats'=>$stats, 'tab'=>$tab, 'search'=>$search, 'collections'=>$rows->fetchAll(PDO::FETCH_ASSOC)]); }
function palPageCollectionDetail(array $rp=[]): void { $u=palCurrentUser(); $id=(int)($rp['id']??$_GET['id']??0); $db=palDb(); $tid=(int)($u['tenant_id']??0); $stmt=$db->prepare("SELECT c.*, COALESCE(s.invoice_number, s.sales_number) AS sales_number, s.net_amount AS sale_net, s.status AS sale_status, p.title AS project_title, cl.name AS client_name, cb.full_name AS created_by_name FROM pal_collections c LEFT JOIN pal_sales s ON c.sales_id=s.id LEFT JOIN pal_projects p ON c.project_id=p.id LEFT JOIN pal_clients cl ON c.client_id=cl.id LEFT JOIN pal_users cb ON c.created_by=cb.id WHERE c.id=:id AND c.tenant_id=:tid"); $stmt->execute([':id'=>$id,':tid'=>$tid]); $col=$stmt->fetch(PDO::FETCH_ASSOC); if(!$col){palJsonError('Collection not found.',404);return;} $t=__DIR__.'/../templates/project-audit-ledger/shell.disyl'; palRender($t, ['current_user'=>$u, 'page_title'=>'Collection #'.$id, 'page_content'=>'collections-detail', 'collection'=>$col]); }
function palPageCollectionForm(): void { $u=palCurrentUser(); $db=palDb(); $tid=(int)($u['tenant_id']??0); $proj=$db->prepare("SELECT id,title FROM pal_projects WHERE tenant_id=:tid AND status IN('approved','started','ongoing','completed') ORDER BY title"); $proj->execute([':tid'=>$tid]); $sales=$db->prepare("SELECT s.id, COALESCE(s.invoice_number, s.sales_number) AS sales_number, s.net_amount, s.gross_amount, s.project_id, p.title AS project_title, cl.name AS client_name, COALESCE((SELECT SUM(amount) FROM pal_collections WHERE sales_id=s.id AND status='approved'),0) AS collected_amt FROM pal_sales s LEFT JOIN pal_projects p ON s.project_id=p.id LEFT JOIN pal_clients cl ON s.client_id=cl.id WHERE s.tenant_id=:tid AND s.status IN('issued','partially_paid') ORDER BY p.title, s.created_at DESC"); $sales->execute([':tid'=>$tid]); $t=__DIR__.'/../templates/project-audit-ledger/shell.disyl'; palRender($t, ['current_user'=>$u, 'page_title'=>'Record Collection', 'page_content'=>'collection-form', 'projects'=>$proj->fetchAll(PDO::FETCH_ASSOC), 'sales'=>$sales->fetchAll(PDO::FETCH_ASSOC)]); }
function palPageSalesPrint(array $rp=[]): void { $u=palCurrentUser(); $id=(int)($rp['id']??$_GET['id']??0); $s=new palSalesService(palDb(), (int)($u['tenant_id']??0), (int)$u['id']); $sale=$s->get($id); if(!$sale){palJsonError('Sale not found.',404);return;} $settings=palSettings(); $t=__DIR__.'/../templates/project-audit-ledger/prints/invoice-print.disyl'; echo app()->render($t, ['sale'=>$sale, 'settings'=>$settings]); }
function palApiSalesStore(): void { palResponseGuard(function(){ $u=palCurrentUser(); palEnforceCsrf(); $data=$_POST; if(!empty($data['items']) && is_string($data['items'])){$data['items']=json_decode($data['items'],true)??[];} $s=new palSalesService(palDb(), (int)($u['tenant_id']??0), (int)$u['id']); $id=$s->create($data); palAudit('pal.sale.created', (int)$u['id'], 'pal_sales', (string)$id, null, []); header('Content-Type: application/json'); echo json_encode(['ok'=>true, 'id'=>$id]); }); }
function palApiSalesUpdate(array $rp = []): void { palResponseGuard(function() use ($rp): void { $u=palCurrentUser(); palEnforceCsrf(); $id=(int)($rp['id']??$_GET['id']??$_POST['id']??0); if($id<=0){palJsonError('Invalid ID.');return;} $data=$_POST; if(!empty($data['items']) && is_string($data['items'])){$data['items']=json_decode($data['items'],true)??[];} $s=new palSalesService(palDb(), (int)($u['tenant_id']??0), (int)$u['id']); $s->update($id, $data); palAudit('pal.sale.updated', (int)$u['id'], 'pal_sales', (string)$id, null, []); header('Content-Type: application/json'); echo json_encode(['ok'=>true]); }); }
function palApiSalesSendEmail(array $rp = []): void { palResponseGuard(function() use ($rp): void { $u=palCurrentUser(); palEnforceCsrf(); $id=(int)($rp['id']??0); if($id<=0){palJsonError('Invalid sales ID.');return;} $s=new palSalesService(palDb(), (int)($u['tenant_id']??0), (int)$u['id']); $sale=$s->get($id); if(!$sale){palJsonError('Sale not found.',404);return;} $db=palDb(); $settings=palSettings(); $companyName=$settings['company_name']??'ZAP-ARTS Signage & Printing Solutions'; $currency=$settings['currency']??'PHP'; $sym=$currency==='PHP'?'₱':'$'; $clientStmt=$db->prepare("SELECT email,name,contact_person FROM pal_clients WHERE id=:id AND tenant_id=:tid"); $clientStmt->execute([':id'=>$sale['client_id'],':tid'=>(int)($u['tenant_id']??0)]); $client=$clientStmt->fetch(PDO::FETCH_ASSOC); if(!$client||empty($client['email'])||!filter_var($client['email'],FILTER_VALIDATE_EMAIL)){palJsonError('Client has no valid email address on file.');return;} $clientName=htmlspecialchars($client['name']??'Valued Client',ENT_QUOTES,'UTF-8'); $clientEmail=$client['email']; $salesNum=htmlspecialchars(!empty($sale['invoice_number'])?$sale['invoice_number']:($sale['sales_number']??(string)$id),ENT_QUOTES,'UTF-8'); $projectTitle=htmlspecialchars($sale['project_title']??'',ENT_QUOTES,'UTF-8'); $modeOfPayment=!empty($sale['mode_of_payment'])?str_replace('_',' ',ucfirst($sale['mode_of_payment'])):''; $scopeOfWork=!empty($sale['scope_of_work'])?str_replace('_',' ',ucfirst($sale['scope_of_work'])):''; $outstanding=$sym.number_format((float)($sale['outstanding']??0),2); $totalCollected=$sym.number_format((float)($sale['total_collected']??0),2); $grossAmt=$sym.number_format((float)($sale['gross_amount']??0),2); $discountAmt=$sym.number_format((float)($sale['discount_amount']??0),2); $taxAmt=$sym.number_format((float)($sale['tax_amount']??0),2); $downPmt=(float)($sale['down_payment']??0); $chargesHtml=''; if((float)($sale['installation_charge']??0)>0){$chargesHtml.='<tr><td style="padding:4px 10px;text-align:right;color:#6b7280;">Installation:</td><td style="padding:4px 10px;text-align:right;">'.$sym.number_format((float)$sale['installation_charge'],2).'</td></tr>';} if((float)($sale['mobilization_charge']??0)>0){$chargesHtml.='<tr><td style="padding:4px 10px;text-align:right;color:#6b7280;">Mobilization:</td><td style="padding:4px 10px;text-align:right;">'.$sym.number_format((float)$sale['mobilization_charge'],2).'</td></tr>';} if((float)($sale['other_charges']??0)>0){$chargesHtml.='<tr><td style="padding:4px 10px;text-align:right;color:#6b7280;">Other Charges:</td><td style="padding:4px 10px;text-align:right;">'.$sym.number_format((float)$sale['other_charges'],2).'</td></tr>';} $itemsHtml=''; if(!empty($sale['items'])){$itemsHtml='<table style="width:100%;border-collapse:collapse;margin-top:12px;font-size:13px;"><thead><tr style="background:#f3f4f6;"><th style="padding:8px 12px;text-align:left;border-bottom:2px solid #e5e7eb;">#</th><th style="padding:8px 12px;text-align:left;border-bottom:2px solid #e5e7eb;">Particulars</th><th style="padding:8px 12px;text-align:center;border-bottom:2px solid #e5e7eb;">UOM</th><th style="padding:8px 12px;text-align:center;border-bottom:2px solid #e5e7eb;">QTY</th><th style="padding:8px 12px;text-align:right;border-bottom:2px solid #e5e7eb;">Unit Price</th><th style="padding:8px 12px;text-align:right;border-bottom:2px solid #e5e7eb;">SqFt Price</th><th style="padding:8px 12px;text-align:right;border-bottom:2px solid #e5e7eb;">Total</th></tr></thead><tbody>'; foreach($sale['items'] as $item){$itemsHtml.='<tr style="border-bottom:1px solid #e5e7eb;"><td style="padding:6px 12px;text-align:center;">'.((int)($item['sort_order']??0)).'</td><td style="padding:6px 12px;">'.htmlspecialchars($item['particulars']??'',ENT_QUOTES,'UTF-8').(!empty($item['material_name'])?' <span style="color:#6b7280;font-size:11px;">('.htmlspecialchars($item['material_name'],ENT_QUOTES,'UTF-8').')</span>':'').'</td><td style="padding:6px 12px;text-align:center;">'.htmlspecialchars($item['uom']??'\u2014',ENT_QUOTES,'UTF-8').'</td><td style="padding:6px 12px;text-align:center;">'.number_format((float)($item['quantity']??1),2).'</td><td style="padding:6px 12px;text-align:right;">'.((float)($item['price_per_unit']??0)>0?$sym.number_format((float)$item['price_per_unit'],2):'\u2014').'</td><td style="padding:6px 12px;text-align:right;">'.((float)($item['price_per_sqft']??0)>0?$sym.number_format((float)$item['price_per_sqft'],2):'\u2014').'</td><td style="padding:6px 12px;text-align:right;font-weight:bold;">'.$sym.number_format((float)($item['line_total']??0),2).'</td></tr>';}$itemsHtml.='</tbody></table>';} $netAmt=$sym.number_format((float)($sale['net_amount']??0),2); $paymentCallout=''; if((float)($sale['outstanding']??0)>0){$paymentCallout='<div style="margin-top:20px;padding:18px;background:#f3f4f6;border:2px solid #d1d5db;border-radius:10px;text-align:center;"><p style="margin:0 0 4px 0;font-size:13px;font-weight:bold;color:#6b7280;text-transform:uppercase;letter-spacing:1px;">AMOUNT DUE</p><p style="margin:0;font-size:24px;font-weight:bold;color:#dc2626;">'.$outstanding.'</p>'.($sale['due_date']?'<p style="margin:6px 0 0 0;font-size:12px;color:#6b7280;">Payment due by '.$sale['due_date'].'</p>':'<p style="margin:6px 0 0 0;font-size:12px;color:#6b7280;">Payment due upon receipt</p>').($downPmt>0?'<p style="margin:6px 0 0 0;font-size:12px;color:#6b7280;">Down payment of '.$sym.number_format($downPmt,2).' applied. Invoice total: '.$netAmt.'</p>':'').((float)($sale['total_collected']??0)>0?'<p style="margin:2px 0;font-size:12px;color:#6b7280;">Already paid: '.$totalCollected.'</p>':'').($modeOfPayment?'<p style="margin:6px 0 0 0;font-size:12px;color:#6b7280;">Accepted payment: '.$modeOfPayment.'</p>':'').'</div>';} $subject='Invoice '.$salesNum.' from '.$companyName; $body='<p>Hi '.$clientName.',</p><p>Please find your invoice from <strong>'.htmlspecialchars($companyName,ENT_QUOTES,'UTF-8').'</strong> below.</p>'.'<table style="width:100%;border-collapse:collapse;margin:16px 0;font-size:13px;"><tr><td style="padding:6px 12px;background:#f3f4f6;font-weight:bold;">Invoice #:</td><td style="padding:6px 12px;background:#f3f4f6;">'.$salesNum.'</td></tr><tr><td style="padding:6px 12px;font-weight:bold;">Date:</td><td style="padding:6px 12px;">'.htmlspecialchars($sale['sales_date']??'',ENT_QUOTES,'UTF-8').'</td></tr><tr><td style="padding:6px 12px;background:#f3f4f6;font-weight:bold;">Due Date:</td><td style="padding:6px 12px;background:#f3f4f6;">'.htmlspecialchars($sale['due_date']??'Upon Receipt',ENT_QUOTES,'UTF-8').'</td></tr>'.($projectTitle?'<tr><td style="padding:6px 12px;font-weight:bold;">Project:</td><td style="padding:6px 12px;">'.htmlspecialchars($projectTitle,ENT_QUOTES,'UTF-8').'</td></tr>':'').($scopeOfWork?'<tr><td style="padding:6px 12px;background:#f3f4f6;font-weight:bold;">Scope:</td><td style="padding:6px 12px;background:#f3f4f6;">'.htmlspecialchars($scopeOfWork,ENT_QUOTES,'UTF-8').'</td></tr>':'').($modeOfPayment?'<tr><td style="padding:6px 12px;font-weight:bold;">Payment:</td><td style="padding:6px 12px;">'.htmlspecialchars($modeOfPayment,ENT_QUOTES,'UTF-8').'</td></tr>':'').'<tr><td style="padding:6px 12px;background:#f3f4f6;font-weight:bold;">Status:</td><td style="padding:6px 12px;background:#f3f4f6;">'.htmlspecialchars(ucfirst($sale['status']??'draft'),ENT_QUOTES,'UTF-8').'</td></tr></table>'.$itemsHtml.'<table style="width:100%;border-collapse:collapse;margin-top:12px;font-size:13px;"><tr><td style="padding:4px 10px;text-align:right;color:#6b7280;">Gross Amount:</td><td style="padding:4px 10px;text-align:right;">'.$grossAmt.'</td></tr>'.((float)($sale['discount_amount']??0)>0?'<tr><td style="padding:4px 10px;text-align:right;color:#6b7280;">Discount:</td><td style="padding:4px 10px;text-align:right;color:#dc2626;">\u2212'.$discountAmt.'</td></tr>':'').((float)($sale['tax_amount']??0)>0?'<tr><td style="padding:4px 10px;text-align:right;color:#6b7280;">Tax:</td><td style="padding:4px 10px;text-align:right;">'.$taxAmt.'</td></tr>':'').$chargesHtml.'<tr style="font-weight:bold;"><td style="padding:6px 10px;text-align:right;border-top:2px solid #2563eb;color:#2563eb;font-size:14px;">NET AMOUNT:</td><td style="padding:6px 10px;text-align:right;border-top:2px solid #2563eb;color:#2563eb;font-size:14px;">'.$netAmt.'</td></tr><tr><td style="padding:4px 10px;text-align:right;color:#6b7280;">Collected:</td><td style="padding:4px 10px;text-align:right;color:#16a34a;">'.$totalCollected.'</td></tr><tr><td style="padding:4px 10px;text-align:right;color:#6b7280;">Outstanding:</td><td style="padding:4px 10px;text-align:right;'.(((float)($sale['outstanding']??0))>0?'color:#dc2626;':'color:#16a34a;').'font-weight:bold;">'.$outstanding.'</td></tr></table>'.$paymentCallout.($sale['notes']?'<hr style="border:none;border-top:1px solid #e5e7eb;margin:16px 0;"><p style="font-size:12px;color:#6b7280;"><strong>Notes:</strong> '.htmlspecialchars($sale['notes'],ENT_QUOTES,'UTF-8').'</p>':'').'<hr style="border:none;border-top:1px solid #e5e7eb;margin:16px 0;"><p style="font-size:12px;color:#6b7280;">View your invoice online:</p><p><a href="'.palBaseUrl().'/admin/project-audit-ledger/sales/'.$id.'" style="display:inline-block;padding:10px 20px;background:#2563eb;color:#fff;text-decoration:none;border-radius:6px;font-size:14px;">View Invoice</a></p><hr style="border:none;border-top:1px solid #e5e7eb;margin:16px 0;"><p style="font-size:11px;color:#9ca3af;">'.htmlspecialchars($companyName,ENT_QUOTES,'UTF-8').(!empty($settings['company_phone'])?' | '.htmlspecialchars($settings['company_phone'],ENT_QUOTES,'UTF-8'):'').(!empty($settings['company_email'])?' | '.htmlspecialchars($settings['company_email'],ENT_QUOTES,'UTF-8'):'').'</p>'; $sent=sendEmail($clientEmail, $subject, $body); if(!$sent){palJsonError('Failed to send email. Check server mail configuration.');} palAudit('pal.sale.emailed',(int)$u['id'],'pal_sales',(string)$id,null,['sent_to'=>$clientEmail]); header('Content-Type: application/json'); echo json_encode(['ok'=>true,'message'=>'Invoice emailed to '.$clientName]); }); }function palApiCollectionStore(): void { palResponseGuard(function(){ $u=palCurrentUser(); palEnforceCsrf(); $s=new palSalesService(palDb(), (int)($u['tenant_id']??0), (int)$u['id']); $id=$s->recordCollection($_POST); palAudit('pal.collection.recorded', (int)$u['id'], 'pal_collections', (string)$id, null, []); header('Content-Type: application/json'); echo json_encode(['ok'=>true, 'id'=>$id]); }); }
function palApiCollectionStatus(array $rp=[]): void { palResponseGuard(function() use ($rp): void { $u=palCurrentUser(); palEnforceCsrf(); $id=(int)($rp['id']??0); if($id<=0){palJsonError('Invalid collection ID.');return;} $status=$_POST['status']??''; if(!in_array($status,['pending','approved','rejected','voided'],true)){palJsonError('Invalid status.');return;} $db=palDb(); $tid=(int)($u['tenant_id']??0); $stmt=$db->prepare("UPDATE pal_collections SET status=:st WHERE id=:id AND tenant_id=:tid"); $stmt->execute([':st'=>$status,':id'=>$id,':tid'=>$tid]); if($stmt->rowCount()===0){palJsonError('Collection not found.',404);return;} // If marking as approved, also update sale collection status
if($status==='approved'){$s=new palSalesService($db,$tid,(int)$u['id']); $colStmt=$db->prepare("SELECT sales_id FROM pal_collections WHERE id=:id"); $colStmt->execute([':id'=>$id]); $col=$colStmt->fetch(PDO::FETCH_ASSOC); if($col){$s->updateSaleCollectionStatus((int)$col['sales_id']);}} palAudit('pal.collection.status',(int)$u['id'],'pal_collections',(string)$id,null,['status'=>$status]); header('Content-Type: application/json'); echo json_encode(['ok'=>true,'message'=>'Status updated to '.$status]); }); }
function palApiCollectionsGenerate(): void { palResponseGuard(function(){ $u=palCurrentUser(); palEnforceCsrf(); $db=palDb(); $tid=(int)($u['tenant_id']??0); $settings=palSettings(); $prefix=$settings['collection_prefix']??'COL'; // Find invoices without any collection
$sql="SELECT s.id, s.sales_number, s.gross_amount, s.down_payment, s.down_payment_type, s.project_id, s.client_id, s.sales_date, s.mode_of_payment, s.created_by FROM pal_sales s LEFT JOIN pal_collections c ON s.id=c.sales_id AND c.tenant_id=s.tenant_id WHERE s.tenant_id=:tid AND s.status IN('issued','partially_paid') AND c.id IS NULL ORDER BY s.id"; $stmt=$db->prepare($sql); $stmt->execute([':tid'=>$tid]); $invoices=$stmt->fetchAll(PDO::FETCH_ASSOC); if(empty($invoices)){header('Content-Type: application/json'); echo json_encode(['ok'=>true,'message'=>'All invoices already have collections.','created'=>0]); return;} $created=0; $errors=0; foreach($invoices as $inv){try{$cCount=$db->prepare("SELECT COUNT(*) FROM pal_collections WHERE tenant_id=:tid"); $cCount->execute([':tid'=>$tid]); $cNum=$prefix.'-'.date('Ymd').'-'.str_pad((string)((int)$cCount->fetchColumn()+1),4,'0',STR_PAD_LEFT); $cAmount=!empty($inv['down_payment'])?(float)$inv['down_payment']:(float)$inv['gross_amount']; $pm=$inv['mode_of_payment']??'cash'; $ins=$db->prepare("INSERT INTO pal_collections (tenant_id, collection_number, sales_id, project_id, client_id, payment_date, amount, payment_method, notes, received_by, status, created_by) VALUES (:t,:cn,:si,:pj,:cl,:pd,:amt,:pm,:no,:rb,:st,:cb)"); $ins->execute([':t'=>$tid,':cn'=>$cNum,':si'=>$inv['id'],':pj'=>$inv['project_id']?:null,':cl'=>$inv['client_id']?:null,':pd'=>$inv['sales_date']??date('Y-m-d'),':amt'=>$cAmount,':pm'=>$pm,':no'=>'Generated from invoice '.$inv['sales_number'],':rb'=>(int)$u['id'],':st'=>'pending',':cb'=>(int)$u['id']]); $created++;}catch(Throwable $e){$errors++; write_log('pal.collections.generate failed for invoice #'.$inv['id'].': '.$e->getMessage(),'error');}} palAudit('pal.collections.generate',(int)$u['id'],'pal_collections',null,null,['created'=>$created,'errors'=>$errors]); header('Content-Type: application/json'); echo json_encode(['ok'=>true,'message'=>"Generated {$created} collection(s).",'created'=>$created,'errors'=>$errors]); }); }
